CREATE TABLE viewer_scores (owner_id TEXT NOT NULL REFERENCES approved_streamers(user_id), viewer_id TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 10), PRIMARY KEY(owner_id, viewer_id));
CREATE TABLE activities (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES approved_streamers(user_id), status TEXT NOT NULL CHECK(status IN ('initializing','open','paused','settling','cancelling','settled','cancelled')), rule_version INTEGER NOT NULL CHECK(rule_version=1), guild_id TEXT CHECK(guild_id IS NULL OR (length(guild_id) BETWEEN 1 AND 32 AND guild_id NOT GLOB '*[^0-9]*')), created_at INTEGER NOT NULL, UNIQUE(id,owner_id));
CREATE UNIQUE INDEX one_unfinished_activity_per_owner ON activities(owner_id) WHERE status IN ('initializing','open','paused','settling','cancelling');
CREATE TABLE activity_score_baselines (activity_id TEXT NOT NULL, owner_id TEXT NOT NULL, viewer_id TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 1 AND 10), PRIMARY KEY(activity_id,viewer_id), FOREIGN KEY(activity_id,owner_id) REFERENCES activities(id,owner_id));
